                "summary": "当地时间6月8日，OpenAI CEO Sam Altman与首席科学家雅各布·帕霍茨基联合发文，宣布公司正式进入第三发展阶段。第一、二阶段分别聚焦AGI研发和全球产品推广，第三阶段核心是让先进AI变得供给充足、成本亲民、安全实用。OpenAI提出三大目标：打造自动化AI研究员、推动经济提速发展、为全球每人配备专属AGI。文章同时强调AI须坚守安全底线并始终处于人类管控之下。",
