                    "summary": "联合国大学水、环境与健康研究所近日发布报告指出，删除AI指令中请、谢谢等礼貌用语可让ChatGPT能耗降低约25%，每年可节约87至98吉瓦时电能，相当于撒哈拉以南非洲76万人全年生活用电。报告还警示当前AI占全球数据中心用电约20%，预计2030年AI年耗电量将达378太瓦时，建议用户精简指令、优先选用轻量化小模型。",
