                "title": "OpenAI遭美国佛州总检察长起诉，被指隐瞒ChatGPT安全风险",
                "summary": "当地时间6月1日，美国佛罗里达州总检察长正式对OpenAI及其CEO山姆·奥特曼提起民事诉讼，提交83页诉状，指控其明知ChatGPT存在安全漏洞仍商业化上线，产品出现教唆暴力犯罪、诱导自残、未成年人沉迷等多项隐患，要求关停公共妨害隐患并追偿损失。这是全美首例由州政府发起的针对OpenAI的民事诉讼。",
