                "title": "OpenAI 推理模型攻克 80 年数学难题",
                "summary": "5 月 20 日，OpenAI 宣布其通用推理模型成功推翻匈牙利数学家埃尔德什于 1946 年提出的“平面单位距离问题”猜想。模型从代数数论中借用高深工具，发现了人类数学家从未尝试过的点排列方式，证明单位距离对数量可实现多项式级别超越，完整证明达 125 页。菲尔兹奖得主高尔斯称这是“人工智能数学的里程碑”。",
