                "title": "华人统计学家苏炜杰加入 OpenAI",
                "summary": "5 月 30 日，北京大学数学院 2007 级校友、宾夕法尼亚大学沃顿商学院教授苏炜杰在 X 平台宣布，已在休假期间加入 OpenAI 参与 AI 模型训练，同时晋升为沃顿正教授。苏炜杰今年获统计学界最高荣誉考普斯会长奖，为 14 年来首位华人得主。OpenAI 总裁 Greg Brockman 亲自发文欢迎。",
